func (this *TextLayout) GetLevel(offset int32) int32 {
	this.CheckLayout()
	this.ComputeRuns()
	var length int32 = jrt.StringLength(this.text)
	if !(0 <= offset && offset <= length) {
		Error(ERROR_INVALID_RANGE)
	}
	offset = this.TranslateOffset(offset)
	var iter int64 = gtk.OSPango_layout_get_iter(this.layout)
	if iter == 0 {
		Error(ERROR_NO_HANDLES)
	}
	var level int32 = 0
	var item gtk.PangoItem = gtk.PangoItem{}
	var run gtk.PangoLayoutRun = gtk.PangoLayoutRun{}
	var ptr int64 = gtk.OSPango_layout_get_text(this.layout)
	var byteOffset int64 = gtk.OSG_utf16_offset_to_pointer(ptr, int64(offset)) - ptr
	var strlen int32 = gtk.CStrlen(ptr)
	byteOffset = int64(math.Min(float64(byteOffset), float64(strlen)))
	for {
		var runPtr int64 = gtk.OSPango_layout_iter_get_run(iter)
		if runPtr != 0 {
			gtk.OSMemmoveOverload19(&run, runPtr, int64(gtk.PangoLayoutRunSizeof))
			gtk.OSMemmoveOverload17(&item, run.Item, int64(gtk.PangoItemSizeof))
			if int64(item.Offset) <= byteOffset && byteOffset < int64(item.Offset+item.Length) {
				level = int32(item.Analysis_level)
				break
			}
		}
		if !(gtk.OSPango_layout_iter_next_run(iter)) {
			break
		}
	}
	gtk.OSPango_layout_iter_free(iter)
	return level
}

