func (this *TextLayout_MetricsAdapter) WantToRealInPango(realMetrics *gtk.PangoRectangle) int32 {
	var wantHeightInPixels int32 = this.lineMetricsInPixels.GetHeight()
	var realHeightInPixels int32 = gtk.OSPANGO_PIXELS(realMetrics.Height)
	if realHeightInPixels == wantHeightInPixels {
		return 0
	}
	var wantAboveInPango int32 = gtk.OSPANGO_SCALE * this.lineMetricsInPixels.GetAscent()
	var realAboveInPango int32 = -realMetrics.Y
	return wantAboveInPango - realAboveInPango
}

